    "Jika pelepasan terbenam elektrik yang diimport ke dalam Kesatuan ditentukan berdasarkan pelepasan sebenar, maklumat bagi bukti dalam titik D.2.4, dan bagaimana pengendali menerimanya",
  "Whether CO2 is captured, stored or used: the identity and contact data of the responsible person at the receiving installation, and the monitoring methodology":
    "Sama ada CO2 ditangkap, disimpan atau digunakan: identiti dan data hubungan orang bertanggungjawab di instalasi penerima, dan metodologi pemantauan",
  "Whether electricity is produced inside the installation, and if so whether by co-generation or separate generation, from fossil or renewable sources, and whether it leaves the system boundary of a production process":
    "Sama ada elektrik dihasilkan di dalam instalasi, dan jika ya sama ada melalui penjanaan bersama atau penjanaan berasingan, daripada sumber fosil atau boleh diperbaharui, dan sama ada ia keluar daripada sempadan sistem proses pengeluaran",
  "Whether measurable heat is imported or exported, which installations, and how the emissions attributed to the heat flows are determined for each production process":
    "Sama ada haba boleh ukur diimport atau dieksport, instalasi yang mana, dan bagaimana pelepasan yang diperuntukkan kepada aliran haba ditentukan bagi setiap proses pengeluaran",
  "Whether zero-rated fuels are used, and how the operator demonstrates that zero-rating applies":
    "Sama ada bahan api kadar sifar digunakan, dan bagaimana pengendali membuktikan kadar sifar terpakai",
  "Zero-rated fuels": "Bahan api kadar sifar",
  "Zero-rated fuels, and how the operator demonstrates that zero-rating applies":
    "Bahan api kadar sifar, dan bagaimana pengendali membuktikan kadar sifar terpakai",
  "Whole year": "Sepanjang tahun",
  "Whole reading": "Keseluruhan bacaan",
  "Unnamed good": "Barangan tanpa nama",
  "The full report the verifier verifies.":
    "Laporan penuh yang disahkan oleh pengesah.",
  "It is in English (Article 10(4)).":
    "Ia dalam bahasa Inggeris (Perkara 10(4)).",
  "The verification reports of the installations that made your precursors on actual values.":
    "Laporan pengesahan instalasi yang menghasilkan prekursor anda pada nilai sebenar.",
  "The reports themselves are in the package, beside this index.":
    "Laporan itu sendiri terdapat dalam pakej, di sebelah indeks ini.",
  "The documents themselves are in the package, beside this index.":
    "Dokumen itu sendiri terdapat dalam pakej, di sebelah indeks ini.",
  "Every document behind a figure, and the figure it supports, so the verifier can sample a month and find its paper.":
    "Setiap dokumen di sebalik angka, dan angka yang disokongnya, supaya pengesah boleh mensampel satu bulan dan mencari dokumennya.",
  "The verifier reads it before the year is verified.":
    "Pengesah membacanya sebelum tahun itu disahkan.",
  "What the installation monitors and how, element by element as the template lists them.":
    "Apa yang dipantau instalasi dan bagaimana, elemen demi elemen seperti yang disenaraikan templat.",
  "Answer 2(f) first": "Jawab 2(f) dahulu",
