    "Sumber: nilai lalai — Peraturan Pelaksanaan (EU) 2025/2621, Lampiran I; penanda aras — 2025/2620; fasa masuk — Artikel 10a Arahan ETS; harga — Artikel 21 Peraturan 2023/956.",
