  "The alloying elements of what was made this month, from the mill test certificates, weighted by the heats cast.":
    "Unsur aloi bagi apa yang dihasilkan bulan ini, daripada sijil ujian kilang, dinilai mengikut haba tuangan.",
  "The report states Mn, Cr, Ni and the other alloying elements for the year: the months' figures, weighted by what was made in each. Leave a month empty if it was ordinary carbon steel with only trace elements.":
    "Laporan menyatakan Mn, Cr, Ni dan unsur aloi lain bagi tahun itu: angka bulanan, dinilai mengikut apa yang dihasilkan setiap bulan. Biarkan bulan kosong jika ia keluli karbon biasa dengan unsur surihan sahaja.",
  "Optional. Weighted by tonnes made across the year in the report.":
    "Pilihan. Dinilai mengikut tan yang dihasilkan sepanjang tahun dalam laporan.",
