    "Supaya pengesah tahu sijil yang perlu diminta.",
  "The alloying elements add up to more than 100 %.":
    "Unsur aloi berjumlah melebihi 100 %.",
  "Ask about CBAM or Certrace": "Tanya tentang CBAM atau Certrace",
  "Text or CSV · one at a time · or press to choose":
    "Teks atau CSV · satu demi satu · atau tekan untuk memilih",
  "What goes to the verifier": "Apa yang dihantar kepada pengesah",
  "Everything this installation hands over for {year}, in one package: the reports you write, and the papers that travel with them.":
    "Semua yang diserahkan instalasi ini untuk {year}, dalam satu pakej: laporan yang anda tulis, dan kertas yang menyertainya.",
  Attachments: "Lampiran",
  "Not reports you write. Each is an index of papers that travel in the package, beside the reports — and neither holds the package back.":
    "Bukan laporan yang anda tulis. Setiap satu ialah indeks kertas yang dibawa dalam pakej, bersama laporan — dan kedua-duanya tidak menahan pakej.",
  "Monitoring plan, operator's emissions report, summary report":
    "Pelan pemantauan, laporan pelepasan pengendali, laporan ringkasan",
  Addendum: "Adendum",
  "Electricity goes to the EU — one per declarant":
    "Elektrik dihantar ke EU — satu bagi setiap pengisytihar",
  "Not needed — no electricity goes to the EU":
    "Tidak diperlukan — tiada elektrik dihantar ke EU",
  "Precursor verification reports, supporting evidence":
    "Laporan pengesahan prekursor, bukti sokongan",
  Contains: "Mengandungi",
  "to get": "perlu diperoleh",
  "Still to get": "Masih perlu diperoleh",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.":
    "Setiap instalasi yang anda laporkan menyerahkan satu pakej setahun: pelan pemantauan, laporan pelepasan pengendali, laporan ringkasan — adendum pengisytihar di mana elektrik dihantar ke EU — dan, bersamanya, laporan pengesahan instalasi prekursor anda serta bukti sokongan. Ia meliputi setiap produk yang dihasilkan tapak, dan dimuat turun apabila semuanya lengkap.",
  documents: "dokumen",
  "The product report is not complete": "Laporan produk belum lengkap",
  "{n} of {total} product reports are not complete":
    "{n} daripada {total} laporan produk belum lengkap",
  "{n} item(s) of the installation's information are still missing":
    "{n} item maklumat instalasi masih belum lengkap",
  "{n} item(s) to do": "{n} item perlu dibuat",
  "Monitoring plan": "Pelan pemantauan",
  "Operator's emissions report": "Laporan pelepasan pengendali",
  "Operator's summary emissions report":
    "Laporan ringkasan pelepasan pengendali",
  "Declarant-specific addendum": "Adendum khusus pengisytihar",
  "Verification reports of precursor installations":
    "Laporan pengesahan instalasi prekursor",
  "Supporting evidence and records": "Bukti sokongan dan rekod",
  "What the installation monitors and how, element by element as the template lists them. The verifier reads it before the year is verified.":
    "Apa yang dipantau instalasi dan cara, elemen demi elemen seperti yang disenaraikan templat. Pengesah membacanya sebelum tahun disahkan.",
  "The full report the verifier verifies. It is in English (Article 10(4)).":
    "Laporan penuh yang disahkan pengesah. Ia dalam bahasa Inggeris (Artikel 10(4)).",
  "The shortened report passed on to authorised CBAM declarants (Article 8).":
    "Laporan ringkas yang diserahkan kepada pengisytihar CBAM yang diberi kuasa (Artikel 8).",
  "One per authorised declarant, only for electricity imported into the EU.":
    "Satu bagi setiap pengisytihar yang diberi kuasa, hanya bagi elektrik yang diimport ke EU.",
  "This installation does not export electricity to the EU, so no addendum is needed.":
    "Instalasi ini tidak mengeksport elektrik ke EU, jadi adendum tidak diperlukan.",
  "The verification reports of the installations that made your precursors on actual values. The reports themselves are in the package, beside this index.":
    "Laporan pengesahan instalasi yang menghasilkan prekursor anda dengan nilai sebenar. Laporannya sendiri ada dalam pakej, bersama indeks ini.",
  "Every document behind a figure, and the figure it supports, so the verifier can sample a month and find its paper. The documents themselves are in the package, beside this index.":
    "Setiap dokumen di sebalik angka, dan angka yang disokongnya, supaya pengesah boleh mensampel satu bulan dan mencari kertasnya. Dokumen itu sendiri ada dalam pakej, bersama indeks ini.",
