  "Have the documents already?": "Sudah ada dokumen?",
  "Add documents and let Certrace fill the form":
    "Tambah dokumen dan biarkan Certrace mengisi borang",
  "Drop this month's bills, fuel invoices and ERP exports. AI reads each one, files it and fills the matching figures. You check everything before it is saved — AI can make mistakes.":
    "Lepaskan bil, invois bahan api dan eksport ERP bulan ini. AI membaca setiap satu, memfailkannya dan mengisi angka yang sepadan. Anda menyemak semuanya sebelum ia disimpan — AI boleh tersilap.",
  "Add documents & auto-fill": "Tambah dokumen & isi automatik",
  "AI reads your bills and invoices and fills the form. You check before saving — AI can make mistakes.":
    "AI membaca bil dan invois anda dan mengisi borang. Anda menyemak sebelum menyimpan — AI boleh tersilap.",
  "Why this is asked": "Mengapa ini ditanya",
  "6 steps — installation, methodology, monthly data, precursors, documents, then check and sign. Everything saves as you type.":
    "6 langkah — instalasi, metodologi, data bulanan, prekursor, dokumen, kemudian semak dan tandatangan. Semua disimpan semasa anda menaip.",
