    "Ini kelihatan bukan sesuatu yang diminta pengesah CBAM.",
  "Pick what this document is first.": "Pilih jenis dokumen ini dahulu.",
  "This product does not count electricity emissions, so the checklist has no electricity row to file it to.":
    "Produk ini tidak mengira pelepasan elektrik, jadi senarai semak tiada baris elektrik untuk memfailkannya.",
  "Pick which month this document covers.":
    "Pilih bulan yang diliputi dokumen ini.",
  "Pick which fuel this is for.": "Pilih bahan api untuk dokumen ini.",
  "Pick a checklist row for this document.":
    "Pilih baris senarai semak untuk dokumen ini.",
  "No checklist row to file to.": "Tiada baris senarai semak untuk difailkan.",
  "Nothing in the file name says what this is. Pick the document type below.":
    "Tiada apa dalam nama fail yang menyatakan ini apa. Pilih jenis dokumen di bawah.",
  "Guessed from the file name only. Nothing inside the file was read, so no values were proposed.":
    "Diteka daripada nama fail sahaja. Tiada apa dalam fail dibaca, jadi tiada nilai dicadangkan.",
  "Electricity bill for March 2026 — 412,800 kWh on meter SMP-7781204.":
    "Bil elektrik untuk Mac 2026 — 412,800 kWh pada meter SMP-7781204.",
  "Scanned electricity bill for April 2026. Several digits are smudged; the total kWh is partly obscured and a handwritten note repeats it with a question mark.":
    "Bil elektrik imbasan untuk April 2026. Beberapa digit kabur; jumlah kWh sebahagiannya tidak jelas dan nota tulisan tangan mengulanginya dengan tanda soal.",
  "Natural gas invoice for March 2026 — 185,400 Sm³ delivered at RY-DP-014.":
    "Invois gas asli untuk Mac 2026 — 185,400 Sm³ dihantar di RY-DP-014.",
  "Delivery note for 12,000 litres of diesel B7 on 18 April 2026. No price on the note.":
    "Nota penghantaran 12,000 liter diesel B7 pada 18 April 2026. Tiada harga pada nota.",
  "ERP production summary for March 2026 — 8,420.5 t of hot-rolled coil.":
    "Ringkasan pengeluaran ERP untuk Mac 2026 — 8,420.5 t gegelung canai panas.",
  "Calibration certificate for gas flow meter GFM-22-0391, calibrated 12 January 2026, next due 12 January 2027.":
    "Sijil penentukuran untuk meter aliran gas GFM-22-0391, ditentukur pada 12 Januari 2026, penentukuran seterusnya pada 12 Januari 2027.",
  "EN 10204 3.1 certificate for 250 t of SS400 slab, heat H26-03117, delivered March 2026.":
    "Sijil EN 10204 3.1 untuk 250 t slab SS400, haba H26-03117, dihantar Mac 2026.",
  "Receipt for paper and printer ink. Nothing on it relates to emissions, energy or production.":
    "Resit untuk kertas dan dakwat pencetak. Tiada apa padanya berkaitan pelepasan, tenaga atau pengeluaran.",
  "Cera Intelligence is coming soon.":
    "Cera Intelligence akan datang tidak lama lagi.",
