  "One report per product.": "Satu laporan bagi setiap produk.",
  "Every product you track gets a report — your own, and any supplier's you have started tracking. Each is built from that product's months, so it always says what its workspace says today.":
    "Setiap produk yang anda jejaki mendapat laporan — produk anda sendiri, dan produk pembekal yang anda mulakan jejaki. Setiap laporan dibina daripada bulan produk itu, jadi ia sentiasa menyatakan apa yang ruang kerjanya nyatakan hari ini.",
