  "Clear the filters, or start a new declaration — CBAM compliance or a custom buyer request.":
    "Kosongkan penapis, atau mulakan pengisytiharan baharu — pematuhan CBAM atau permintaan pembeli tersuai.",
  "Scope it once.": "Skopkan sekali.",
  "Suppliers fill a free guided form — no account, no seat.":
    "Pembekal mengisi borang berpandu percuma — tiada akaun, tiada tempat duduk.",
