  "Pick up where you left off from the Declarations list.":
    "Sambung dari tempat anda berhenti dalam senarai Pengisytiharan.",
  "Declaration created.": "Pengisytiharan dicipta.",
  "{name} — {suppliers} suppliers · {products} products · {lots} lots queued.":
    "{name} — {suppliers} pembekal · {products} produk · {lots} lot dalam baris gilir.",
  "Compliance regulation": "Peraturan pematuhan",
  "Which regime are you reporting for? Certrace launched on CBAM — the obligation that bites first for exporters into the EU. The rest run on the same engine and switch on as their data models are verified.":
    "Rejim mana yang anda laporkan? Certrace dilancarkan pada CBAM — kewajipan yang terpakai dahulu bagi pengeksport ke EU. Yang lain berjalan pada enjin yang sama dan diaktifkan apabila model datanya disahkan.",
  "Export route": "Laluan eksport",
  "Where do you export from, and into which market? {reg} applies to goods entering the EU — your origin sets the emission-factor library Certrace calculates with.":
    "Dari mana anda mengeksport, dan ke pasaran mana? {reg} terpakai kepada barang yang masuk ke EU — asal anda menentukan pustaka faktor pelepasan yang digunakan Certrace untuk mengira.",
  "From — country of origin": "Dari — negara asal",
  "To — destination market": "Ke — pasaran destinasi",
  "Enforces {reg}": "Menguatkuasakan {reg}",
  "No {reg} obligation here": "Tiada kewajipan {reg} di sini",
  "factors from": "faktor daripada",
  "filed to": "difailkan ke",
