  "United States": "Amerika Syarikat",
  "Coming soon · electronics, steel, textiles.":
    "Tidak lama lagi · elektronik, keluli, tekstil.",
  "Coming soon · aluminium, palm oil (EUDR).":
    "Tidak lama lagi · aluminium, minyak sawit (EUDR).",
  "Planned · rubber, palm oil, electronics.":
    "Dirancang · getah, minyak sawit, elektronik.",
  "EU CBAM Registry · via importer / declarant":
    "Daftar CBAM EU · melalui pengimport / pengisytihar",
  "What is this declaration for?": "Untuk apa pengisytiharan ini?",
  "Choose one — the official CBAM filing, or a specific buyer's data request. Each has its own qualification checklist, so keep the two separate.":
    "Pilih satu — pemfailan CBAM rasmi, atau permintaan data pembeli tertentu. Setiap satu mempunyai senarai semak kelayakan sendiri, jadi asingkan kedua-duanya.",
  "CBAM Compliance": "Pematuhan CBAM",
  "Automatically prepares supplier data collection based on CBAM requirements. Fields, CN codes and templates are generated for you.":
    "Menyediakan pengumpulan data pembekal secara automatik berdasarkan keperluan CBAM. Medan, kod CN dan templat dijana untuk anda.",
  "Buyer Request": "Permintaan Pembeli",
  "Create a custom supplier request for buyer-specific information — documents, certificates and questionnaires on top of the carbon data.":
    "Cipta permintaan pembekal tersuai untuk maklumat khusus pembeli — dokumen, sijil dan soal selidik di samping data karbon.",
  "e.g. CBAM 2026 Annual": "cth. CBAM 2026 Tahunan",
  "e.g. ABC Buyer Carbon Data Request":
    "cth. Permintaan Data Karbon Pembeli ABC",
  "Request name": "Nama permintaan",
  "Shown to suppliers and on every reminder. Make it recognisable.":
    "Dipaparkan kepada pembekal dan pada setiap peringatan. Jadikan ia mudah dikenali.",
  "Request description (optional)": "Penerangan permintaan (pilihan)",
  "Context for your suppliers — what this is for.":
    "Konteks untuk pembekal anda — untuk apa ini.",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.":
    "cth. Data karbon CBAM tahunan bagi eksport keluli EU kami. Sila laporkan pada peringkat instalasi.",
  "EU buyer / importer (required)": "Pembeli / pengimport EU (wajib)",
  "EU buyer / importer": "Pembeli / pengimport EU",
  "Who imports these goods into the EU? Their Authorised CBAM Declarant files the declaration — Certrace addresses the Communication Template and the O3CI share to them.":
    "Siapa yang mengimport barang ini ke EU? Pengisytihar CBAM yang diberi kuasa mereka memfailkan pengisytiharan — Certrace menghantar Templat Komunikasi dan perkongsian O3CI kepada mereka.",
  "The buyer this data request is for.":
    "Pembeli yang untuknya permintaan data ini.",
  "Buyer legal name": "Nama sah pembeli",
  "EORI number": "Nombor EORI",
  "Format: 2-letter country + 6–15 characters, e.g. DE551234567890":
    "Format: 2 huruf negara + 6–15 aksara, cth. DE551234567890",
  "The declarant's Registry identifier.": "Pengenal Daftar pengisytihar.",
  "Contact email": "E-mel hubungan",
  "Enter a valid email address.": "Masukkan alamat e-mel yang sah.",
  "Where the Communication Template is sent.":
    "Ke mana Templat Komunikasi dihantar.",
  "Buyer requests can run on any cadence. Pick the rhythm that matches how this buyer wants the data.":
    "Permintaan pembeli boleh berjalan pada sebarang kekerapan. Pilih rentak yang sepadan dengan cara pembeli ini mahukan data.",
  "Official CBAM declarations are annual — but you can collect supplier data quarterly if that fits your cycle.":
    "Pengisytiharan CBAM rasmi adalah tahunan — tetapi anda boleh mengumpul data pembekal setiap suku tahun jika sesuai dengan kitaran anda.",
  Quarterly: "Suku tahunan",
  "Semi-annual": "Separuh tahunan",
  "Official CBAM cadence — recommended. Suppliers can report at year-end.":
    "Kekerapan CBAM rasmi — disyorkan. Pembekal boleh melapor pada akhir tahun.",
  "Collect supplier data each quarter (one quarter at a time).":
    "Kumpul data pembekal setiap suku tahun (satu suku pada satu masa).",
  "Once per calendar year.": "Sekali setiap tahun kalendar.",
  "One half-year at a time.": "Satu separuh tahun pada satu masa.",
