  "Search the CBAM goods catalogue by product name, CN code or HS code. Pick everything in scope — reorder to match how you brief suppliers.":
    "Cari katalog barang CBAM mengikut nama produk, kod CN atau kod HS. Pilih semua dalam skop — susun semula mengikut cara anda memaklumkan pembekal.",
  "Search… e.g. Hot-rolled coil, 7208, or aluminium":
    "Cari… cth. Gegelung canai panas, 7208, atau aluminium",
  "All goods": "Semua barang",
  "Iron & Steel": "Besi & Keluli",
  "{count} in catalogue": "{count} dalam katalog",
  "No products match “{query}”.": "Tiada produk sepadan dengan “{query}”.",
  "In scope": "Dalam skop",
  "Nothing selected yet. Tick products on the left to add them.":
    "Belum ada yang dipilih. Tanda produk di sebelah kiri untuk menambahnya.",
  "Move up": "Alih ke atas",
  "Move down": "Alih ke bawah",
  "Classification & report fields": "Pengelasan & medan laporan",
  "Certrace classified each product automatically — category, CN / HS codes and the CBAM template come from the catalogue and can't be edited. The checklist below reflects the data points that actually apply to the goods you selected.":
    "Certrace mengelaskan setiap produk secara automatik — kategori, kod CN / HS dan templat CBAM diambil daripada katalog dan tidak boleh disunting. Senarai semak di bawah mencerminkan titik data yang benar-benar terpakai kepada barang yang anda pilih.",
  "CBAM report fields": "Medan laporan CBAM",
  "Carbon data to request": "Data karbon untuk diminta",
  "{included} of {total} included": "{included} daripada {total} disertakan",
  "These are the data points CBAM requires for the goods you selected. Required fields are locked on; the rest are recommended and on by default — keep or drop them to match how you collect data.":
    "Ini ialah titik data yang diperlukan CBAM untuk barang yang anda pilih. Medan wajib dikunci hidup; selebihnya disyorkan dan hidup secara lalai — simpan atau buang mengikut cara anda mengumpul data.",
  "Choose the carbon-data fields this buyer needs. Recommended fields are pre-selected because buyers commonly ask for them — adjust freely, keeping at least one.":
    "Pilih medan data karbon yang diperlukan pembeli ini. Medan disyorkan dipilih terlebih dahulu kerana pembeli lazimnya memintanya — laraskan dengan bebas, dengan sekurang-kurangnya satu dikekalkan.",
