  "Certificate price in EUR per tonne CO2e":
    "Harga sijil dalam EUR setiap tan CO2e",
  "Carbon hotspots": "Titik panas karbon",
  "Ranked by absolute chargeable emissions across every declaration in scope — the same mill appearing on four filings counts once, as one relationship.":
    "Disusun mengikut pelepasan boleh dikenakan mutlak merentasi setiap pengisytiharan dalam skop — kilang yang sama muncul dalam empat pemfailan dikira sekali, sebagai satu hubungan.",
  "by supplier": "mengikut pembekal",
