  "{datasets} submitted supplier datasets across {declarations} declarations, costed with the same engine the declaration workspace uses — the Annex II direct-only rule for steel and aluminium, default-value markups where a supplier reported on defaults, and any carbon price already paid deducted. Nothing here is a filed figure.":
    "{datasets} set data pembekal yang dihantar merentasi {declarations} pengisytiharan, dikira dengan enjin yang sama digunakan ruang kerja pengisytiharan — peraturan hanya-langsung Lampiran II bagi keluli dan aluminium, mark-up nilai lalai apabila pembekal melapor menggunakan nilai lalai, dan harga karbon yang telah dibayar ditolak. Tiada apa di sini ialah angka yang difailkan.",
