  "Every supplier submission must be approved before the report can be generated — the package only ever contains verified data.":
    "Setiap penghantaran pembekal mesti diluluskan sebelum laporan boleh dijana — pakej hanya mengandungi data yang disahkan.",
  "Generate the report first — sign-off is a confirmation of the exact package that will be sent.":
    "Jana laporan dahulu — kelulusan ialah pengesahan bagi pakej tepat yang akan dihantar.",
  "Internal sign-off must be complete before anything is dispatched — every requested confirmation has to land first.":
    "Kelulusan dalaman mesti lengkap sebelum apa-apa dihantar — setiap pengesahan yang diminta mesti diterima dahulu.",
  "Awaiting review": "Menunggu semakan",
  "Changes requested": "Perubahan diminta",
  Approved: "Diluluskan",
  "Supplier submissions": "Penghantaran pembekal",
  "Each supplier filled their own Smart Link, the AI checked it, they e-signed and submitted. Open a submission to read the data, loop in your internal reviewers, then approve it or request a revision.":
    "Setiap pembekal mengisi Smart Link mereka sendiri, AI menyemaknya, mereka menandatangani secara elektronik dan menghantar. Buka penghantaran untuk membaca data, libatkan penyemak dalaman anda, kemudian luluskannya atau minta semakan semula.",
  "{count} of these products are produced by you — no link goes out for them; fill them in here and they run through the same checks.":
    "{count} daripada produk ini dihasilkan oleh anda — tiada pautan dihantar untuk mereka; isikannya di sini dan ia melalui semakan yang sama.",
  "Reminder sent": "Peringatan dihantar",
