  "LINE ID": "ID LINE",
  "So our CBAM specialists can reach you on LINE.":
    "Supaya pakar CBAM kami boleh menghubungi anda melalui LINE.",
  "Enter a real telephone number — digits only, 6 to 14 of them.":
    "Masukkan nombor telefon yang sebenar — digit sahaja, 6 hingga 14 digit.",
