  "Nothing here is transmitted automatically — this browser only, until you submit.":
    "Tiada apa di sini dihantar secara automatik — hanya dalam pelayar ini, sehingga anda menghantar.",
  "Saved as you go — you can close this page and come back to it from any device.":
    "Disimpan semasa anda meneruskan — anda boleh menutup halaman ini dan kembali daripada mana-mana peranti.",
