  "Accept with a reason": "Terima dengan sebab",
  "Verification report": "Laporan pengesahan",
  "Generate buyer summary package": "Jana pakej ringkasan pembeli",
  "avoided this year, so far": "dielakkan tahun ini, setakat ini",
  "Suppliers and Reports stay in the left nav — they are quick, frequent jobs, and burying them under a declaration would guarantee they never get done.":
    "Pembekal dan Laporan kekal di navigasi kiri — ia kerja pantas dan kerap, dan menyembunyikannya di bawah pengisytiharan akan memastikan ia tidak pernah disiapkan.",
  "No anomalies or gaps — figures are complete, in range and standardised.":
    "Tiada anomali atau jurang — angka lengkap, dalam julat dan diseragamkan.",
  "Send revision request": "Hantar permintaan semakan",
  "sha-256 sealed · verification trail + version history embedded":
    "bermeterai sha-256 · jejak pengesahan + sejarah versi disertakan",
