  Questionnaire: "Soal selidik",
  Invite: "Jemput",
  "No colleagues yet — you can fill everything yourself, or invite the right people above.":
    "Belum ada rakan sekerja — anda boleh mengisi semuanya sendiri, atau jemput orang yang sesuai di atas.",
  "Units validated": "Unit disahkan",
  "No warnings": "Tiada amaran",
