  "This precursor has no workspace of its own yet. Track a report for it and its own months, readiness and settings open here.":
    "Prekursor ini belum ada ruang kerja sendiri. Jejak laporan untuknya dan bulan, kesediaan dan tetapannya sendiri dibuka di sini.",
  "Not sent": "Tidak dihantar",
  "Sent — pending": "Dihantar — menunggu",
