  supplier: "pembekal",
  "tier deep": "peringkat dalam",
  "tiers deep": "peringkat dalam",
  "submitted earlier": "dihantar lebih awal",
  "not started (critical)": "belum dimulakan (kritikal)",
  "No Smart Link goes out for these — {supplier} is you. Report the embedded emissions of your own installation the same way an external supplier would, and the declaration treats it identically: same {regulation} checklist, same AI check, same verification trail.":
    "Tiada Pautan Pintar dihantar untuk ini — {supplier} ialah anda. Laporkan pelepasan terbenam pemasangan anda sendiri dengan cara yang sama seperti pembekal luar, dan pengisytiharan memprosesnya dengan cara yang sama: senarai semak {regulation} yang sama, semakan AI yang sama, jejak pengesahan yang sama.",
  "You’re {supplier}. To keep shipping {origin} {sector} into the {destination}, {exporter} has to report the embedded emissions of the goods they buy from you — under {regulation}. This takes about 10 minutes, it’s free, and you don’t need an account.":
    "Anda ialah {supplier}. Untuk terus menghantar {origin} {sector} ke {destination}, {exporter} perlu melaporkan pelepasan terbenam barangan yang mereka beli daripada anda — di bawah {regulation}. Ini mengambil masa kira-kira 10 minit, percuma, dan anda tidak perlukan akaun.",
  "Your figures are checked automatically before you submit and land in your own supplier record, so the next declaration starts pre-filled instead of blank. Colleagues can be assigned the sections that belong to their department.":
    "Angka anda disemak secara automatik sebelum anda menghantar dan masuk ke dalam rekod pembekal anda sendiri, jadi pengisytiharan seterusnya bermula dengan isi awal dan bukan kosong. Rakan sekerja boleh ditugaskan bahagian yang tergolong dalam jabatan mereka.",
  "Your figures are checked automatically before you submit, encrypted, and shared only with {exporter} for this declaration. You can invite colleagues to fill the parts that belong to their department.":
    "Angka anda disemak secara automatik sebelum anda menghantar, disulitkan, dan hanya dikongsi dengan {exporter} untuk pengisytiharan ini. Anda boleh menjemput rakan sekerja mengisi bahagian yang tergolong dalam jabatan mereka.",
  "Reporting as": "Melapor sebagai",
  "Requested by": "Diminta oleh",
  "Goods in scope": "Barangan dalam skop",
  "Documents requested": "Dokumen diminta",
  "{total} ({required} required)": "{total} ({required} diperlukan)",
  "One request for the period": "Satu permintaan untuk tempoh ini",
