  "Certificate of Origin (COO)": "Sijil Asal (COO)",
  "Verification statement (accredited verifier)":
    "Kenyataan pengesahan (pengesah yang diakreditasi)",
  "Please report at installation level using actual data where you have it. If you only have default factors, mark the method as “default”. Reach out if anything is unclear — we'd rather help than receive a guess.":
    "Sila laporkan di peringkat pemasangan menggunakan data sebenar jika anda ada. Jika anda hanya ada faktor lalai, tandakan kaedah sebagai “lalai”. Hubungi kami jika ada yang tidak jelas — kami lebih suka membantu daripada menerima tekaan.",
  "Who produced the goods and where.":
    "Siapa yang menghasilkan barangan dan di mana.",
  "Route and quantity per good.": "Laluan dan kuantiti setiap barangan.",
  "Direct & indirect emissions per tonne.":
    "Pelepasan langsung & tidak langsung setiap tan.",
  "Fuel, power and materials the figure is derived from.":
    "Bahan api, kuasa dan bahan angka itu diperoleh daripadanya.",
  "Power use & grid factor (electrolysis goods).":
    "Penggunaan kuasa & faktor grid (barangan elektrolisis).",
  "Embedded emissions carried in from inputs.":
    "Pelepasan terbenam yang dibawa masuk daripada input.",
