  "{amount} on the EU default": "{amount} pada nilai lalai EU",
  "Needs a certificate price and a year from 2026":
    "Perlukan harga sijil dan tahun dari 2026",
  "Supply chain health": "Kesihatan rantaian bekalan",
  "{n} in your chain, {m} on track":
    "{n} dalam rantaian anda, {m} mengikut jadual",
