    "Tambah berat satu keping untuk melihat ini setiap keping.",
  "Edit prices": "Sunting harga",
  "Everything else in the price": "Segala yang lain dalam harga",
  "What is left of the price is not profit: wages, materials and every other cost are still in it.":
    "Baki harga bukan keuntungan: gaji, bahan dan setiap kos lain masih termasuk di dalamnya.",
