  "Sample numbers: switch them off to enter your own.":
    "Nombor sampel: matikannya untuk memasukkan nombor anda sendiri.",
  "Selling price": "Harga jualan",
  "฿ / tonne": "฿ / tan",
  "Weight of one piece": "Berat satu keping",
  "Turns every figure into a per-piece one.":
    "Menukar setiap angka kepada angka setiap keping.",
  "Tonnes shipped to the EU": "Tan dihantar ke EU",
  "The certificate bill is on these. Left empty, all tonnes made are assumed.":
    "Bil sijil dikenakan atas ini. Jika dibiarkan kosong, semua tan yang dihasilkan dianggap.",
